  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.</p>": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">Yeni bir sayfa beyaz tahtanız olarak açılacak. Tüm tuval üzerinde özgürce çizim yapabilir, şekiller, yapışkan notlar ve bağlantılar ekleyebilirsiniz.</p>",
  "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">Cancel</button>": "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">İptal</button>",
  "<button id=\"board-confirm-ok\" style=\"padding:8px 18px;border-radius:8px;border:none;background:var(--gold);color:#111;font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;\">Open Board</button>": "<button id=\"board-confirm-ok\" style=\"padding:8px 18px;border-radius:8px;border:none;background:var(--gold);color:#111;font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;\">Panoyu aç</button>",
  "background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:28px 32px;max-width:420px;width:90%;text-align:center;box-shadow:0 12px 40px rgba(0,0,0,0.5);": "background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:28px 32px;max-width:420px;width:90%;text-align:center;box-shadow:0 12px 40px rgba(0,0,0,0.5);",
  "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">Board Already Exists</h3>": "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">Pano zaten mevcut</h3>",
  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">There is already an open board ": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">Zaten açık bir pano var ",
  "<button id=\"board-choice-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;white-space:nowrap;\">Cancel</button>": "<button id=\"board-choice-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;white-space:nowrap;\">İptal</button>",
  "<button id=\"board-choice-switch\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--gold);background:transparent;color:var(--gold);font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;white-space:nowrap;\">Go to Existing Board</button>": "<button id=\"board-choice-switch\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--gold);background:transparent;color:var(--gold);font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;white-space:nowrap;\">Mevcut panoya git</button>",
