  "<div class=\"bulk-builder-empty-title\">No panel connection</div>": "<div class=\"bulk-builder-empty-title\">Panel bağlantısı yok</div>",
  "<div class=\"bulk-builder-empty-sub\">The product library is available when the editor is opened with a design from the panel. In this tab, you can use the Excel or AI source.</div>": "<div class=\"bulk-builder-empty-sub\">Ürün kitaplığı, editör panelden bir tasarımla açıldığında kullanılabilir. Bu sekmede Excel veya yapay zekâ kaynağını kullanabilirsiniz.</div>",
