  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>Önce tasarımdaki en az bir nesneye (sağ panel) bir Tasarım Alanı atayın, ardından AI bunları dolduracaktır.</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "Bu istek Toplu Oluşturucu'dan (PLAN geçişi) gelir. Talimatı ve tasarım alanlarını okuyun, ardından üreteceğiniz çıktıları LİSTELEYİN, YALNIZCA ETİKETLER (alan içeriği yok). YALNIZCA ham bir JSON nesnesi döndürün: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Çeviri doğru olduğunda, etiketler DİL ADLARI'dır (kullanıcının kullandığı dilde yazılmıştır). Aksi halde, etiketler çıktı başına ayrı bir kısa konu/tohumdur. Talimatta adı geçen herhangi bir miktara saygı gösterin; aksi takdirde mantıklı bir set (yaklaşık 6 ila 12). Sert kapak 500.\n",
