  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Built by <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Geliştiren: <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Released under the Business Source License 1.1.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">© 2026 Mirex Ajansı. Business Source License 1.1.</div> kapsamında yayınlandı",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Reset clears only the wizard's own record. Your projects, settings and keys are untouched.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Sıfırlama yalnızca sihirbazın kendi kaydını temizler. Projeleriniz, ayarlarınız ve anahtarlarınız değişmez.</div>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Need help? Contact us:</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Yardıma mı ihtiyacınız var? Bize ulaşın:</p>",
  "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visit our website</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Web sitemizi ziyaret edin</a></div>",
  "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Email support@dika.studio</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">support@dika.studio adresine e-posta gönderin</a></div>",
