  "<span class=\"pref-rail-icon\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"/><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07\"/></svg></span>": "<span class=\"pref-rail-icon\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"/><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07\"/></svg></span>",
  "<span class=\"pref-rail-icon\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 9V5a3 3 0 0 0-6 0v4\"/><rect x=\"5\" y=\"9\" width=\"14\" height=\"12\" rx=\"2\"/></svg></span>": "<span class=\"pref-rail-icon\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 9V5a3 3 0 0 0-6 0v4\"/><rect x=\"5\" y=\"9\" width=\"14\" height=\"12\" rx=\"2\"/></svg></span>",
  "<span class=\"pref-rail-icon\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18\"/><path d=\"M9 3v18\"/></svg></span>": "<span class=\"pref-rail-icon\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18\"/><path d=\"M9 3v18\"/></svg></span>",
  "<span class=\"sp-acc-ico\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg></span>": "<span class=\"sp-acc-ico\" style=\"color:var(--text-dim)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg></span>",
  "<p style=\"font-size:11px;color:var(--text-dim);margin:0 0 12px\">Automatically delete items in the gallery trash after a set period.</p>": "<p style=\"font-size:11px;color:var(--text-dim);margin:0 0 12px\">Galerinin çöp kutusundaki öğeleri belirlenen süreden sonra otomatik olarak silin.</p>",
  "<span class=\"sp-acc-ico\" style=\"color:var(--red)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></span>": "<span class=\"sp-acc-ico\" style=\"color:var(--red)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></span>",
  "<span class=\"sp-acc-title\" style=\"color:var(--red)\">Danger Zone</span>": "<span class=\"sp-acc-title\" style=\"color:var(--red)\">Tehlikeli bölge</span>",
  "<p style=\"font-size:11px;color:var(--text-dim);margin:0 0 10px\">This will clear all saved data including profile, templates, preferences, and downloaded AI subtitle models.</p>": "<p style=\"font-size:11px;color:var(--text-dim);margin:0 0 10px\">Bu işlem profil, şablonlar, tercihler ve indirilen yapay zekâ altyazı modelleri dahil tüm kayıtlı verileri temizler.</p>",
  "<div style=\"display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 10px;padding:8px 10px;border:1px solid var(--border);border-radius:6px\">": "<div style=\"display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 10px;padding:8px 10px;border:1px solid var(--border);border-radius:6px\">",
  "<span style=\"font-size:11px;color:var(--text-dim)\">AI subtitle models cache</span>": "<span style=\"font-size:11px;color:var(--text-dim)\">Yapay zekâ altyazı modelleri önbelleği</span>",
  "<span id=\"set-model-cache-size\" style=\"font-size:12px;font-weight:600;color:var(--text)\">&hellip;</span>": "<span id=\"set-model-cache-size\" style=\"font-size:12px;font-weight:600;color:var(--text)\">…</span>",
  "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Clear All Cache</button>": "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Tüm önbelleği temizle</button>",
  "settings: preferences": "settings: preferences",
  "<p style=\"color:var(--text-dim);font-size:12px;margin-bottom:14px\">Your profile data is used in contact presets and bulk export.</p>": "<p style=\"color:var(--text-dim);font-size:12px;margin-bottom:14px\">Profil verileriniz kişi hazır ayarlarında ve toplu dışa aktarımda kullanılır.</p>",
  "<button class=\"sbtn\" id=\"settings-save-profile\" style=\"margin-top:16px;width:100%;height:auto;padding:10px 16px;font-size:13px;background:var(--gold);color:#111;font-weight:600;border-radius:8px\">Save Profile</button>": "<button class=\"sbtn\" id=\"settings-save-profile\" style=\"margin-top:16px;width:100%;height:auto;padding:10px 16px;font-size:13px;background:var(--gold);color:#111;font-weight:600;border-radius:8px\">Profili kaydet</button>",
