  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Bu tarayıcıdan süreleri otomatik olarak kaydedin. En son durum <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span> altında saklanır; yuvarlanan anlık görüntüler için <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p> kullanılır",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">Henüz <code>dika_autosave</code> kaydı yok.</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Kayıtlı sürüm anlık görüntülerini temizler (<code>dika_versions</code>). Geçerli tuval ve en son otomatik kaydetme dosyası kaldırılmaz.</span>",
