  "A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.": "Yeni sayfa beyaz tahtanız olarak açılacak. Tüm tuval üzerinde serbestçe çizim yapabilir, şekiller, yapışkan notlar ve bağlayıcılar ekleyebilirsiniz.",
