  "Add products from the panel's Assets > Products section, and they'll appear here automatically.": "Panelin Varlıklar > Ürünler bölümünden ürünler ekleyin; ürünler burada otomatik olarak görünecektir.",
  "A design and video studio that runs on this machine.": "Bu makinede çalışan bir tasarım ve video stüdyosu.",
  "Your work stays here. Documents, media and version history never leave this computer.": "Senin işin burada kalacak. Belgeler, medya ve sürüm geçmişi bu bilgisayardan asla ayrılmaz.",
  "Free to use. Source available under the Business Source License 1.1.": "Kullanımı ücretsiz. Kaynak kodu Business Source License 1.1 altında yayınlanır.",
  "Your projects are stored in this browser profile. That is the only copy.": "Projeleriniz bu tarayıcı profilinde saklanır. Tek kopya budur.",
  "Clearing site data deletes them. So does a different browser, or a fresh profile.": "Site verilerinin temizlenmesi, bunların silinmesine neden olur. Farklı bir tarayıcı veya yeni bir profil de öyle.",
  "Export a project file for anything you want to keep. It carries the design and its media, and it opens on any machine.": "Saklamak istediğiniz her şey için bir proje dosyasını dışa aktarın. Tasarımı ve ortamını taşır ve her makinede açılır.",
  "Export a project file now": "Şimdi bir proje dosyasını dışa aktarın",
  "Remind me to export": "Dışa aktarmayı hatırlat",
  "Never": "Asla",
  "Weekly": "Haftalık",
  "Monthly": "Aylık",
  "That is everything. Your work stays on this machine.": "Her şey bu. İşiniz bu makinede kalır.",
  "You can reopen this from Settings > About.": "Bunu Ayarlar > Hakkında'dan tekrar açabilirsiniz.",
  "Start using it": "Kullanmaya başlayın",
  "Your profile data is used in contact presets and bulk export.": "Profil verileriniz kişi hazır ayarlarında ve toplu dışa aktarımda kullanılır.",
  "JOB TITLE": "İŞ UNVANI",
  "ADDRESS": "ADRES",
  "Social Media": "Sosyal Medya",
  "Save Profile": "Profili kaydet",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "Hesap; çevrim içi şablonlara, varlık kitaplığına ve sürüm haberlerine erişim sağlar. Editör çevrim içi veya çevrim dışı çalışır.",
  "Sign in to unlock:": "Kilidi açmak için oturum açın:",
  "The online template and asset library": "Çevrimiçi şablon ve varlık kitaplığı",
  "Release news and early access to new features": "Yayın haberleri ve yeni özelliklere erken erişim",
  "The editor itself works either way, with or without an account, online or offline.": "Editörün kendisi, hesapla veya hesapsız, çevrimiçi veya çevrimdışı olarak her iki şekilde de çalışır.",
  "Create an account": "Hesap oluştur",
  "WHAT THIS APP SENDS": "BU UYGULAMA NELER GÖNDERİR",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "Günde bir kez: oturum açtığınızda yükleme kimliği, uygulama sürümü, platformunuz ve diliniz ve hesap kimliğiniz.",
  "Nothing about your designs. No document, no title, no file name, no image.": "Tasarımlarınız hakkında bilgi yok: belge, başlık, dosya adı veya görsel bulunamadı.",
  "WHERE THE SESSION IS KEPT": "OTURUMUN NEREDE TUTULDUĞU",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "Her yerel sayfanın bir depolama alanını paylaştığı tarayıcı yapısını çalıştırıyorsunuz, böylece bu tarayıcıda açılan başka bir yerel dosya bu oturumu okuyabilir. Bu nedenle kısa ömürlüdür (yaklaşık 24 saat) ve yalnızca şablon kitaplığını okuyabilir. Masaüstü uygulaması kendi yalıtılmış depolama alanını korur.",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "Stok medya sağlayıcılarına ait anahtarlarınız. Bu anahtarlar, Görseller ve Ses arama sekmeleriyle Öğeler içindeki GIF ve Çıkartmalar sekmelerini doldurur. Aşağıdaki her sağlayıcıda ücretsiz kullanım kotası vardır.",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "Bu anahtarlar yalnızca bu tarayıcıda saklanır ve bu yapı, bunları hiçbir zaman sağlayıcının kendisi dışında herhangi bir yere göndermez. Bu bilgisayara veya tarayıcı profiline erişimi olan herkes bunları okuyabilir, bu nedenle ihtiyacınız olan en düşük kotaya sahip kısıtlı bir anahtar kullanın.",
  "Save keys": "Anahtarları kaydet",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. unsplash.com/oauth/applications adresine gidin ve bir uygulama oluşturun",
  "2. Copy the Access Key, not the Secret Key": "2. Gizli Anahtarı değil Erişim Anahtarını kopyalayın",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "Başlık: Yetkilendirme: Client-ID YOUR_KEY - Demoda 50 talep/saat, üretimde 5000 talep/saat",
  "1. Go to pexels.com/api and request a key": "1. pexels.com/api adresine gidin ve bir anahtar isteyin",
  "2. It is issued instantly": "2. Anında verilir",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "Başlık: Yetkilendirme: YOUR_KEY - 200 talep/saat, 20K talep/ay",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. pixabay.com/api/docs/ adresine gidin ve kaydolun",
  "2. Copy the key shown on the docs page": "2. Dokümanlar sayfasında gösterilen anahtarı kopyalayın",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "500.000'den fazla CC lisanslı ses efekti - başlık: Yetkilendirme: Token YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. freesound.org/apiv2/apply adresine gidin ve bir API uygulaması oluşturun",
  "2. Copy the API Token": "2. API Simgesini kopyalayın",
  "1. Go to devportal.jamendo.com and register an app": "1. devportal.jamendo.com adresine gidin ve bir uygulamayı kaydedin",
  "2. Copy the Client ID": "2. İstemci Kimliğini kopyalayın",
  "1. Go to developers.giphy.com and create an app": "1. Developers.giphy.com adresine gidin ve bir uygulama oluşturun",
  "2. Copy the API Key": "2. API Anahtarını kopyalayın",
