  "Auto-save times from this browser. The latest state is stored under dika_autosave; rolling snapshots use dika_versions.": "Bu tarayıcıdan süreleri otomatik olarak kaydedin. En son durum,dika_autosave altında saklanır; yuvarlanan anlık görüntüler,dika_versions'ı kullanır.",
  "Clear History": "Geçmişi Temizle",
  "Customize shortcuts, manage profiles, and resolve conflicts across all app modules.": "Kısayolları özelleştirin, profilleri yönetin ve tüm uygulama modüllerindeki çakışmaları çözün.",
