  "Skip Startup Wizard": "Başlangıç ​​Sihirbazını Atla",
  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "Çok sayfalı projelerde uygulamayı hızlı tutmak için uzun süre açmadığınız sayfalar arka planda uykuya alınır. İçerikleri güvenle saklanır ve sekmesine tıkladığınızda hemen geri gelir. Çalıştığınız sayfa, yakındaki birkaç sayfa ve video / sonsuz tuval / slayt / pano sayfaları her zaman açık kalır.",
  "Automatic sleep": "Otomatik uyku",
  "Maximum awake pages (pages older than this number sleep)": "Maksimum açık sayfa (bu sayıdan eski sayfalar uykuya alınır)",
  "Neighbor window (pages kept awake on each side of the active page)": "Komşu penceresi (etkin sayfanın her iki yanındaki sayfalar açık tutulur)",
  "AWAKE": "UYANMAK",
