  "Concurrent Uploads": "Eşzamanlı Yüklemeler",
  "1 (Sequential)": "1 (Sıralı)",
  "3 (Default)": "3 (Varsayılan)",
  "Number of images processed at once. Use 1 for weak servers, Unlimited for local.": "Aynı anda işlenen görsel sayısı. Düşük güçlü sunucular için 1, yerel kullanım için Sınırsız seçin.",
  "Rate Limit": "Oran Limiti",
  "Maximum images per minute. Useful for rate-limited servers.": "Dakika başına maksimum görüntü. Hızı sınırlı sunucular için kullanışlıdır.",
  "Show progress modal": "İlerleme modunu göster",
  "Image Settings": "Görsel ayarları",
  "Max File Size": "Maksimum Dosya Boyutu",
  "Files larger than this will be skipped.": "Bundan daha büyük dosyalar atlanacaktır.",
  "Image compression is done automatically during upload (Settings → Storage → Performance).": "Görüntü sıkıştırma, yükleme sırasında otomatik olarak yapılır (Ayarlar → Depolama → Performans).",
  "Queue Status": "Kuyruk Durumu",
  "Multi-Product Design Platform": "Çok ürünlü tasarım platformu",
  "Built by dika.studio": "dika.studio tarafından geliştirildi",
  "Remove everything": "Her şeyi kaldır",
  "Deletes every project, page, version, uploaded file, font, brand set, saved key, setting and account on this machine, and puts the app back to how it arrived. It cannot be undone.": "Bu makinedeki her projeyi, sayfayı, sürümü, yüklenen dosyayı, yazı tipini, marka setini, kayıtlı anahtarı, ayarı ve hesabı siler ve uygulamayı geldiği haline geri getirir. Bu işlem geri alınamaz.",
  "Export a project file first if you want to keep anything. This does not uninstall the program itself: use Windows Settings for that.": "Herhangi bir şeyi saklamak istiyorsanız önce bir proje dosyasını dışa aktarın. Bu, programın kendisini kaldırmaz: bunun için Windows Ayarlarını kullanın.",
  "Radial Tool Menu": "Radyal Takım Menüsü",
  "Compact arc menu for quick tool access. Max 10 slots.": "Araçlara hızlı erişim için kompakt yay menüsü. Maksimum: 10 slots.",
