  "No rolling snapshots yet (they are added on each auto-save tick).": "Henüz döngüsel anlık görüntü yok (her otomatik kaydetme döngüsünde eklenir).",
  "Clears stored version snapshots (dika_versions). Current canvas and latest auto-save file are not removed.": "Kayıtlı sürüm anlık görüntülerini temizler (dika_versions). Geçerli tuval ve en son otomatik kaydetme dosyası kaldırılmaz.",
